## Essential Concepts to Master

### 1. Environment Variables

Never hardcode sensitive information:

```javascript
// .env file
DATABASE_URL=postgresql://user:pass@localhost:5432/mydb
JWT_SECRET=your-secret-key
PORT=3001

// In your code
require('dotenv').config();

const dbUrl = process.env.DATABASE_URL;
const port = process.env.PORT || 3000;
```

### 2. Error Handling

```javascript
// Backend error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    error: 'Something went wrong!',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// Frontend error handling
try {
  const response = await fetch('/api/data');

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }

  const data = await response.json();
} catch (error) {
  console.error('Failed to fetch data:', error);
  // Show error message to user
}
```

### 3. Authentication Flow

```javascript
// Simple JWT authentication example

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { email, password } = req.body;

  // Verify credentials (check database)
  const user = await User.findByEmail(email);

  if (!user || !await user.verifyPassword(password)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Create JWT token
  const token = jwt.sign({ userId: user.id }, process.env.JWT_SECRET);

  res.json({ token, user: { id: user.id, email: user.email } });
});

// Protected endpoint
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/api/profile', authenticateToken, (req, res) => {
  // req.user contains the authenticated user data
  res.json({ userId: req.user.userId });
});
```

## Database Basics

### SQL vs NoSQL

**SQL (PostgreSQL, MySQL)**
- Structured data with relationships
- ACID compliant (reliable transactions)
- Good for: Banking, e-commerce, traditional apps

```sql
-- Create users table
CREATE TABLE users (
  id SERIAL PRIMARY KEY,
  name VARCHAR(100),
  email VARCHAR(100) UNIQUE,
  created_at TIMESTAMP DEFAULT NOW()
);

-- Insert user
INSERT INTO users (name, email) VALUES ('John', 'john@example.com');

-- Query users
SELECT * FROM users WHERE email = 'john@example.com';
```

**NoSQL (MongoDB)**
- Flexible schema
- Document-based
- Good for: Real-time apps, social media, content management

```javascript
// MongoDB with Mongoose
const userSchema = new mongoose.Schema({
  name: String,
  email: { type: String, unique: true },
  createdAt: { type: Date, default: Date.now }
});

const User = mongoose.model('User', userSchema);

// Create user
const user = await User.create({
  name: 'John',
  email: 'john@example.com'
});

// Find user
const user = await User.findOne({ email: 'john@example.com' });
```

